#!/usr/bin/env python3
"""GMI #833 AE7 -- route B.  Materially independent oracle.

Imports NOTHING from route A.  Every quantity is rebuilt by a different method:

  * sensors are generated by the insert-into-a-block recursion over frozensets,
    not by restricted-growth strings;
  * the control value of a sensor is obtained by ENUMERATING EVERY
    deterministic policy measurable with respect to it and taking the maximum,
    not by per-block aggregate maximisation;
  * "merging a pair of states is free" is decided by comparing exact VALUES
    before and after the merge, not by intersecting optimal-action sets;
  * predictive profiles are built by direct counting over states.

Utilities are carried as integers scaled by 32 (their exact common
denominator), so route B never performs a Fraction operation inside its inner
loop and cannot inherit a rounding habit from route A.  Values are restored as
exact Fractions at the boundary.

    python3 -I -B independent_control_oracle_v1.py
"""

from fractions import Fraction as F
import json
import sys

N = 8
SCALE = 32          # exact common denominator of every registered utility
PRIOR_DEN = 8       # uniform prior 1/8


def bits(s):
    return (s & 1, (s >> 1) & 1, (s >> 2) & 1)


ACTIONS = ("a0", "a1", "a2", "a3")


def u_hidden(s, a):
    b2 = bits(s)[2]
    if a == "a0":
        return SCALE if b2 == 0 else 0
    if a == "a1":
        return SCALE if b2 == 1 else 0
    return SCALE // 2


def u_visible(s, a):
    b0 = bits(s)[0]
    if a == "a0":
        return SCALE if b0 == 0 else 0
    if a == "a1":
        return SCALE if b0 == 1 else 0
    return SCALE // 4


_HELLY = {0: ("a0", "a1"), 1: ("a1", "a2"), 2: ("a2", "a0")}


def u_helly(s, a):
    if s in _HELLY:
        return SCALE if a in _HELLY[s] else 0
    return SCALE if a == "a3" else 0


def u_graded(s, a):
    b = bits(s)
    v = b[0] + 2 * b[1] + 4 * b[2]
    if a == "a0":
        return v * (SCALE // 8)
    if a == "a1":
        return (7 - v) * (SCALE // 8)
    if a == "a2":
        return SCALE // 2 + (v % 3) * (SCALE // 16)
    return 3 * (SCALE // 8) + (v % 5) * (SCALE // 32)


UTILS = (("U_hidden_coordinate", u_hidden),
         ("U_visible_coordinate", u_visible),
         ("U_helly_triple", u_helly),
         ("U_graded", u_graded))

TARGETS = (
    ("Y_b0", lambda s: bits(s)[0]),
    ("Y_b1", lambda s: bits(s)[1]),
    ("Y_xor01", lambda s: bits(s)[0] ^ bits(s)[1]),
    ("Y_and01", lambda s: bits(s)[0] & bits(s)[1]),
    ("Y_or01", lambda s: bits(s)[0] | bits(s)[1]),
    ("Y_pair01", lambda s: 2 * bits(s)[0] + bits(s)[1]),
)


# ---------------------------------------------------------------- sensors ---

def gen_partitions(n):
    """Insert-into-a-block recursion; returns sorted tuples of sorted blocks."""
    parts = [((0,),)]
    for e in range(1, n):
        nxt = []
        for p in parts:
            for i in range(len(p)):
                q = list(p)
                q[i] = tuple(sorted(q[i] + (e,)))
                nxt.append(tuple(sorted(q)))
            nxt.append(tuple(sorted(list(p) + [(e,)])))
        parts = nxt
    return sorted(set(parts))


def labelling(part):
    """Canonical block-label string, so route A and route B can be compared."""
    lab = [0] * N
    for i, blk in enumerate(sorted(part, key=lambda b: min(b))):
        for s in blk:
            lab[s] = i
    return "".join(str(x) for x in lab)


def refines(a, b):
    """Every block of a is inside some block of b."""
    where = {}
    for i, blk in enumerate(b):
        for s in blk:
            where[s] = i
    for blk in a:
        tgt = where[blk[0]]
        for s in blk:
            if where[s] != tgt:
                return False
    return True


# ------------------------------------------------- value by enumeration -----

def value_scaled(part, ufn):
    """max over EVERY deterministic policy measurable wrt `part`.

    Returned as an integer in units of 1/(PRIOR_DEN*SCALE).
    """
    k = len(part)
    tab = [[ufn(s, a) for a in ACTIONS] for s in range(N)]
    best = None
    na = len(ACTIONS)
    pol = [0] * k
    while True:
        tot = 0
        for i, blk in enumerate(part):
            ai = pol[i]
            for s in blk:
                tot += tab[s][ai]
        if best is None or tot > best:
            best = tot
        j = k - 1
        while j >= 0:
            pol[j] += 1
            if pol[j] < na:
                break
            pol[j] = 0
            j -= 1
        if j < 0:
            break
    return best


def to_fraction(scaled):
    return F(scaled, PRIOR_DEN * SCALE)


# ---------------------------------------------------- predictive profile ----

def profile(part):
    rows = []
    for blk in part:
        mass = F(len(blk), N)
        cond = []
        for name, tg in TARGETS:
            vals = sorted(set(tg(s) for s in range(N)))
            law = tuple(str(F(sum(1 for s in blk if tg(s) == v), N) / mass)
                        for v in vals)
            cond.append((name, law))
        rows.append((str(mass), tuple(cond)))
    return tuple(sorted(rows))


# ------------------------------------------------------------------- run ----

def main():
    parts = gen_partitions(N)
    labs = [labelling(p) for p in parts]

    vals = {}
    for uname, ufn in UTILS:
        vals[uname] = [value_scaled(p, ufn) for p in parts]

    full = tuple((s,) for s in range(N))
    blind = (tuple(range(N)),)
    ifull = parts.index(tuple(sorted(full)))
    iblind = parts.index(tuple(sorted(blind)))

    # PC-1: same predictive profile, different control value
    groups = {}
    for i, p in enumerate(parts):
        groups.setdefault(profile(p), []).append(i)
    pc1 = {}
    for uname, _ in UTILS:
        v = vals[uname]
        c = 0
        for g in groups.values():
            for a in range(len(g)):
                for b in range(a + 1, len(g)):
                    if v[g[a]] != v[g[b]]:
                        c += 1
        pc1[uname] = c

    sens_b2 = tuple(sorted((tuple(s for s in range(N) if bits(s)[2] == 0),
                            tuple(s for s in range(N) if bits(s)[2] == 1))))
    sens_x = tuple(sorted(
        (tuple(s for s in range(N) if bits(s)[0] ^ bits(s)[2] == 0),
         tuple(s for s in range(N) if bits(s)[0] ^ bits(s)[2] == 1))))
    named = {
        "sensor_A": labelling(sens_b2),
        "sensor_B": labelling(sens_x),
        "identical_predictive_profile": profile(sens_b2) == profile(sens_x),
        "control_value_A": str(to_fraction(
            vals["U_hidden_coordinate"][parts.index(sens_b2)])),
        "control_value_B": str(to_fraction(
            vals["U_hidden_coordinate"][parts.index(sens_x)])),
    }

    # PC-2: control-sufficient and coarsest control-sufficient sensors
    pc2 = {}
    for uname, _ in UTILS:
        vf = vals[uname][ifull]
        suff = set(i for i in range(len(parts)) if vals[uname][i] == vf)
        minimal = []
        for i in suff:
            strict = False
            for j in suff:
                if j != i and refines(parts[i], parts[j]):
                    strict = True
                    break
            if not strict:
                minimal.append(i)
        pc2[uname] = {
            "V_full": str(to_fraction(vf)),
            "V_blind": str(to_fraction(vals[uname][iblind])),
            "control_sufficient_sensors": len(suff),
            "coarsest_control_sufficient_sensors": len(minimal),
            "unique_coarsest": len(minimal) == 1,
        }

    # PC-4: value of information over every comparable pair, by value only
    voi_zero = 0
    voi_pos = 0
    pairs = 0
    for i in range(len(parts)):
        for j in range(len(parts)):
            if i == j:
                continue
            if refines(parts[i], parts[j]):
                pairs += 1
                d = vals["U_graded"][i] - vals["U_graded"][j]
                if d == 0:
                    voi_zero += 1
                else:
                    voi_pos += 1

    # PC-5 / PC-6 decided by VALUE, not by argmax intersection
    free_pairs = {}
    for uname, ufn in UTILS:
        vf = vals[uname][ifull]
        nfree = 0
        for a in range(N):
            for b in range(a + 1, N):
                merged = [(x,) for x in range(N) if x not in (a, b)]
                merged.append((a, b))
                merged = tuple(sorted(merged))
                if value_scaled(merged, ufn) == vf:
                    nfree += 1
        free_pairs[uname] = nfree

    pred_eq = {}
    for s in range(N):
        pred_eq.setdefault(tuple(tg(s) for _, tg in TARGETS), []).append(s)
    redundant = []
    for g in pred_eq.values():
        for i in range(len(g)):
            for j in range(i + 1, len(g)):
                redundant.append((g[i], g[j]))
    pc6 = {}
    for uname, ufn in UTILS:
        vf = vals[uname][ifull]
        n = 0
        for (a, b) in redundant:
            merged = [(x,) for x in range(N) if x not in (a, b)]
            merged.append((a, b))
            merged = tuple(sorted(merged))
            if value_scaled(merged, ufn) != vf:
                n += 1
        pc6[uname] = n

    # PC-7: the five frozen predictions, recomputed from route B's values
    ladder = [F(n, 16) for n in range(0, 33)]
    costs = [len(p) - 1 for p in parts]
    per_problem = {}
    r1 = 0
    r2 = 0
    r4 = 0
    r5 = 0
    for uname, _ in UTILS:
        seq = []
        for pi in ladder:
            best = None
            tie = []
            for i in range(len(parts)):
                j = to_fraction(vals[uname][i]) - pi * costs[i]
                if best is None or j > best:
                    best, tie = j, [i]
                elif j == best:
                    tie.append(i)
            sel = min(tie, key=lambda i: (costs[i], labs[i]))
            seq.append(sel)
        distinct = []
        for i in seq:
            if not distinct or distinct[-1] != i:
                distinct.append(i)
        for t in range(len(seq) - 1):
            if not refines(parts[seq[t]], parts[seq[t + 1]]):
                r1 += 1
        if len(set(distinct)) >= 3:
            r2 += 1
        vf = vals[uname][ifull]
        hi = to_fraction(vf - vals[uname][iblind]) + F(1, 16)
        best = None
        selhi = None
        for i in range(len(parts)):
            j = to_fraction(vals[uname][i]) - hi * costs[i]
            if best is None or j > best:
                best, selhi = j, i
        if len(parts[selhi]) != 1:
            r4 += 1
        found = False
        for i in set(distinct):
            if vals[uname][i] == vf:
                for _, tg in TARGETS:
                    tp = {}
                    for s in range(N):
                        tp.setdefault(tg(s), []).append(s)
                    tpart = tuple(sorted(tuple(v) for v in tp.values()))
                    if not refines(parts[i], tpart):
                        found = True
                        break
            if found:
                break
        if found:
            r5 += 1
        per_problem[uname] = {
            "distinct_selected_sensors": len(set(distinct)),
            "selection_sequence": [labs[i] for i in distinct],
        }

    out = {
        "schema": "GMI_833_AE7_INDEPENDENT_ORACLE_V1",
        "route": "B",
        "method": ("insert-recursion sensors; value by exhaustive policy "
                   "enumeration in scaled integers; free merges decided by "
                   "value difference, not by optimal-action intersection"),
        "sensors_enumerated": len(parts),
        "distinct_predictive_profiles": len(groups),
        "PC_1_same_predictive_different_control_pairs": pc1,
        "PC_1_named_witness": named,
        "PC_2": pc2,
        "PC_4": {
            "comparable_sensor_pairs_checked": pairs,
            "pairs_with_zero_value_of_information": voi_zero,
            "pairs_with_positive_value_of_information": voi_pos,
        },
        "PC_5_free_state_pairs": free_pairs,
        "PC_6_predictively_redundant_state_pairs": len(redundant),
        "PC_6_control_relevant_among_them": pc6,
        "PC_7": {
            "per_problem": per_problem,
            "R1_violations": r1,
            "R2_problems_with_three_or_more": r2,
            "R4_failures": r4,
            "R5_problems_witnessing": r5,
        },
    }
    sys.stdout.write(json.dumps(out, indent=2) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
